INSERT INTO `SERVMASK_PREFIX_options` VALUES (3371,'woocommerce_bacs_settings','a:11:{s:7:\"enabled\";s:2:\"no\";s:5:\"title\";s:58:\"Ví điện tử MoMo / ZaloPay / VNPAY / VietQR (Sandbox)\";s:11:\"description\";s:108:\"Hệ thống sẽ chuyển sang màn hình quét mã QR và tự động xác thực thanh toán tức thì.\";s:12:\"instructions\";s:1776:\"<div style=\"max-width: 480px;margin: 20px auto;background: #ffffff;border: 1px solid #e1e8ed;border-radius: 12px;overflow: hidden;font-family: Arial, sans-serif\">\n  \n  <!-- Header Cổng MoMo / VNPAY -->\n  <div style=\"background: linear-gradient(135deg, #a50064 0%, #d82d8b 100%);color: white;padding: 18px;text-align: center\">\n    <h3 style=\"margin: 0;font-size: 17px;color: #ffffff;font-weight: bold\">CỔNG THANH TOÁN MOMO / VNPAY (SANDBOX)</h3>\n    <p style=\"margin: 4px 0 0 0;font-size: 12px;opacity: 0.9\">Hệ thống thanh toán thử nghiệm TopGear Store</p>\n  </div>\n\n  <!-- Mã QR &amp; Khung Trạng Thái -->\n  <div style=\"padding: 20px;text-align: center\">\n    <div style=\"display: inline-block;padding: 10px;background: #f8f9fa;border: 2px dashed #d82d8b;border-radius: 12px;margin-bottom: 12px\">\n      <img src=\"https://img.vietqr.io/image/MB-0123456789-compact2.png?amount=&amp;addInfo=TopGear%20Sandbox\" alt=\"Mã QR Sandbox\" style=\"width: 190px;height: 190px;display: block;margin: 0 auto;border-radius: 8px\">\n    </div>\n\n    <!-- Thông báo Thành Công -->\n    <div style=\"background: #e8f5e9;border: 1px solid #c8e6c9;border-radius: 8px;padding: 12px;margin-top: 8px\">\n      <div style=\"color: #2e7d32;font-weight: bold;font-size: 15px;margin-bottom: 3px\">\n        ✅ THANH TOÁN HOÀN TẤT THÀNH CÔNG!\n      </div>\n      <p style=\"margin: 0;font-size: 12px;color: #388e3c\">\n        Giao dịch Sandbox đã được xác thực tự động. Đơn hàng đang được chuẩn bị đóng gói.\n      </p>\n    </div>\n\n    <div style=\"margin-top: 12px;font-size: 11px;color: #777\">\n      Mã giao dịch: <strong>TG-SANDBOX-8899</strong> | Trạng thái: <span style=\"color: #2e7d32;font-weight: bold\">PAID_SUCCESS</span>\n    </div>\n  </div>\n</div>\";s:15:\"account_details\";s:0:\"\";s:12:\"account_name\";s:0:\"\";s:14:\"account_number\";s:0:\"\";s:9:\"sort_code\";s:0:\"\";s:9:\"bank_name\";s:0:\"\";s:4:\"iban\";s:0:\"\";s:3:\"bic\";s:0:\"\";}','on');
