INSERT INTO `SERVMASK_PREFIX_postmeta` VALUES (256,38,'wcf-dynamic-css','.cartflows_step-template .select2-container--default .select2-results__option--highlighted[aria-selected], .cartflows_step-template .select2-container--default .select2-results__option--highlighted[data-selected], .wcf-embed-checkout-form { --wcf-primary-color: #df453e;--wcf-heading-color: #161616;--wcf-btn-bg-color: #df453e;--wcf-btn-bg-hover-color: #b62d25;--wcf-btn-text-color: #ffffff;--wcf-btn-hover-text-color: #ffffff;}body .wcf-embed-checkout-form.wcf-embed-checkout-form-instant-checkout { --wcf-primary-color: #df453e;--wcf-heading-color: #161616;--wcf-heading-font-weight: 400;--wcf-field-min-height: 33px;--wcf-btn-bg-color: #df453e;--wcf-btn-bg-hover-color: #b62d25;--wcf-btn-text-color: #ffffff;--wcf-btn-hover-text-color: #ffffff;--wcf-ic-left-column-bg-color: #ffffff;--wcf-ic-right-column-bg-color: #f5f5f5;}\n	.wcf-embed-checkout-form .wcf-checkout-header-image img{\n		width: px;\n	}\n	.wcf-embed-checkout-form .woocommerce #payment input[type=checkbox]:focus,\n	.wcf-embed-checkout-form .woocommerce .woocommerce-shipping-fields [type=\'checkbox\']:focus,\n	.wcf-embed-checkout-form .woocommerce #payment input[type=radio]:checked:focus,\n	.wcf-embed-checkout-form .woocommerce #payment input[type=radio]:not(:checked):focus{\n		box-shadow: 0 0 2px rgba( 223,69,62, .8);\n	}\n\n	.wcf-embed-checkout-form .woocommerce-checkout #payment div.payment_box{\n		background-color: ;\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n\n	.wcf-embed-checkout-form #add_payment_method #payment div.payment_box::before,\n	.wcf-embed-checkout-form .woocommerce-cart #payment div.payment_box::before,\n	.wcf-embed-checkout-form .woocommerce-checkout #payment div.payment_box::before\n	{\n	    border-bottom-color: ;\n	    border-right-color: transparent;\n	    border-left-color: transparent;\n	    border-top-color: transparent;\n	    position: absolute;\n	}\n\n	.wcf-embed-checkout-form .woocommerce #payment [type=\'radio\']:checked + label,\n	.wcf-embed-checkout-form .woocommerce #payment [type=\'radio\']:not(:checked) + label{\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n\n	.wcf-embed-checkout-form #order_review .wcf-custom-coupon-field input[type=\'text\'],\n	.wcf-embed-checkout-form .woocommerce form .form-row input.input-text,\n	.wcf-embed-checkout-form .woocommerce form .form-row textarea,\n	.wcf-embed-checkout-form .select2-container--default .select2-selection--single,\n	.wcf-embed-checkout-form .woocommerce form .form-row select.select {\n		border-color: ;\n		padding-top: px;\n		padding-bottom: px;\n		padding-left: px;\n		padding-right: px;\n		min-height: 33px;\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n\n	.wcf-embed-checkout-form .woocommerce .col2-set .col-1,\n	.wcf-embed-checkout-form .woocommerce .col2-set .col-2,\n	.wcf-embed-checkout-form .woocommerce-checkout .shop_table,\n	.wcf-embed-checkout-form .woocommerce-checkout #order_review_heading,\n	.wcf-embed-checkout-form .woocommerce-checkout #payment,\n	.wcf-embed-checkout-form .woocommerce form.checkout_coupon\n	{\n		background-color: ;\n		border-color: ;\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n\n\n	.wcf-embed-checkout-form .woocommerce form p.form-row label {\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n	.wcf-embed-checkout-form .woocommerce form #payment button,\n	.wcf-embed-checkout-form .woocommerce form.woocommerce-form-login .form-row button {\n		padding-top: px;\n		padding-bottom: px;\n		padding-left: px;\n		padding-right: px;\n		border-color: #df453e;\n		min-height: 33px;\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n\n	.wcf-embed-checkout-form .woocommerce #order_review .wcf-custom-coupon-field .wcf-submit-coupon.button{\n		border-color: #df453e;\n		min-height: 33px;\n		font-family: \'Roboto\', sans-serif;\n	    font-weight: 500;\n	}\n	.wcf-embed-checkout-form .