INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2213,1,'2026-09-10 20:31:23','2026-09-10 20:31:23','THÔNG TIN SẢN PHẨM:\r\n\r\nKích thước: 42 x 28 x 16 cm\r\n\r\nChất liệu: Vải Polyester Canvas cao cấp chống thấm nước\r\n\r\nNgăn chống sốc: Đựng vừa laptop 15,6 inch (35cmx25cm)\r\n\r\nNhiều ngăn nhỏ tiện lợi phía trong balo.\r\n\r\nKích thước được đo thực tế trên bề mặt phẳng trước khi đóng gói.\r\n\r\nSai số 1-2cm có thể xảy ra do đặc tính chất liệu.\r\n\r\nKhông ảnh hưởng đến thiết kế và công năng sản phẩm.','Balo Laptop Tối Giản AURA Minimalist Backpack','','publish','open','closed','','balo-laptop-toi-gian-aura-minimalist-backpack','','','2026-09-26 06:17:03','2026-09-26 06:17:03','',0,'https://nhom4ecom.gt.tc/?post_type=product&#038;p=2213',0,'product','',1);
