INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2220,1,'2026-09-11 04:31:55','2026-09-11 04:31:55','<div class=\"box-title is-flex is-justify-content-space-between is-align-items-center\">\r\n<h2 class=\"title\">Thông số kỹ thuật</h2>\r\n<div class=\"icon-svg\"></div>\r\n</div>\r\n<table class=\"technical-content\">\r\n<tbody>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại card đồ họa</td>\r\n<td>NVIDIA GeForce RTX 3050 6GB GDDR6, Boost Clock 990MHz, TGP 65W</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Dung lượng RAM</td>\r\n<td>16GB</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại RAM</td>\r\n<td>SODIMM DDR5-4800</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Số khe ram</td>\r\n<td>2 khe (Tối đa 16GB DDR5-4800)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Ổ cứng</td>\r\n<td>512GB SSD M.2 2242 PCIe 4.0x4 NVMe (Hỗ trợ tối đa hai ổ đĩa, 2 ổ SSD M.2, tối đa 1TB)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Công nghệ màn hình</td>\r\n<td>Độ sáng 300nits\r\nMàn hình chống chói\r\nĐộ phủ màu 100% sRGB\r\nFreeSync</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Hệ điều hành khi ra mắt</td>\r\n<td>Windows 11 Home Single Language, English</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại CPU</td>\r\n<td>AMD Ryzen 7 170 (8 lõi / 16 luồng, 3.2 / 4.75GHz, 4MB L2 / 16MB L3)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Kích thước màn hình</td>\r\n<td>15.6 inches</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Độ phân giải màn hình</td>\r\n<td>1920 x 1080 pixels (FullHD)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Pin</td>\r\n<td>57.5Wh, 135W Slim Tip (3-pin)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Cổng giao tiếp</td>\r\n<td>2 x USB-A (USB 3.2 Gen 1, 5Gbps)\r\n1 x USB-C (USB 3.2 Gen 1, 5Gbps, PD 3.0)\r\n1 x HDMI 2.1 (tối đa 8K/60Hz)\r\n1 x Jack tai nghe/micro 3,5mm\r\n1 x Ethernet (RJ-45)\r\n1 x Khe đọc thẻ\r\n1 x Cổng nguồn Slim Tip</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div id=\"cpsContentSEO\">\r\n\r\n&nbsp;\r\n\r\n</div>','Laptop Lenava XZ-9180QW','','publish','open','closed','','laptop-lenava-xz-9180qw','','','2026-09-25 04:50:53','2026-09-25 04:50:53','',0,'https://nhom4ecom.gt.tc/?post_type=product&#038;p=2220',0,'product','',0);
