INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2227,1,'2026-09-11 06:33:55','2026-09-11 06:33:55','<div class=\"box-title is-flex is-justify-content-space-between is-align-items-center\">\r\n<h2 class=\"title\">Thông số kỹ thuật</h2>\r\n<div class=\"icon-svg\"></div>\r\n</div>\r\n<table class=\"technical-content\">\r\n<tbody>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại card đồ họa</td>\r\n<td>RTX 5050 (8GB of GDDR7 SDRAM, Bus Width: 128- bit)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Dung lượng RAM</td>\r\n<td>16GB</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại RAM</td>\r\n<td>DDR5 4800MHz</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Số khe ram</td>\r\n<td>2 khe (1 x 16GB, nâng cấp tối da 64GB)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Ổ cứng</td>\r\n<td>512GB SSD1 PCIe (M.2 2280) Gen4x4 2x M.2 SSD slots (Supports 2x PCIe NVMe M.2 SSD, Up to 4TB)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Kích thước màn hình</td>\r\n<td>16 inches</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Công nghệ màn hình</td>\r\n<td>Màn hình chống chói</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Pin</td>\r\n<td>4 Cell Int (76.1Wh)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Hệ điều hành</td>\r\n<td>Windows 11 Home Single Language 64-bit</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Độ phân giải màn hình</td>\r\n<td>1920 x 1200 pixels (FullHD+)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại CPU</td>\r\n<td>AMD Ryzen 7 170 (8 x 3.20 GHz) - Max. Boost Clock: Up to 4. 75 GHz</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Cổng giao tiếp</td>\r\n<td>1 x USB 2.0 Type-A\r\n2 x USB 3.2 Gen 1 Type-A\r\n1 x USB 3.2 Gen 1 Type-C (Power Delivery, DisplayPort)\r\n1 x HDMI\r\n1 x RJ45 (LAN)\r\n1 x Jack tai nghe/mic 3.5 mm\r\n1 x khe PCIe SSD2 (M.2 2280)</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div id=\"cpsContentSEO\">\r\n\r\n&nbsp;\r\n\r\n</div>','Laptop Neonspace Gaming A17','','publish','open','closed','','laptop-neonspace-gaming-a17','','','2026-09-25 04:52:29','2026-09-25 04:52:29','',0,'https://nhom4ecom.gt.tc/?post_type=product&#038;p=2227',0,'product','',0);
