INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2352,1,'2026-10-10 06:29:59','2026-10-10 06:29:59','<div class=\"box-title is-flex is-justify-content-space-between is-align-items-center\">\r\n<h2 class=\"title\">Thông số kỹ thuật</h2>\r\n<div class=\"icon-svg\"></div>\r\n</div>\r\n<table class=\"technical-content\">\r\n<tbody>\r\n<tr class=\"technical-content-item\">\r\n<td>Chip AI</td>\r\n<td>Up to 49 TOPS</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại card đồ họa</td>\r\n<td>Intel Graphics</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Dung lượng RAM</td>\r\n<td>32GB</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại RAM</td>\r\n<td>Soldered LPDDR5X-7467</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Số khe ram</td>\r\n<td>Không nâng cấp</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Ổ cứng</td>\r\n<td>1TB SSD M.2 2242 PCIe 4.0x4 NVMe (Một ổ đĩa, SSD M.2 2242 dung lượng lên đến 2TB)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Công nghệ màn hình</td>\r\n<td>Độ sáng 400 nits (typical), 600 nits (peak)\r\nĐộ phủ màu 100% DCI-P3, 100% sRGB\r\nEyesafe\r\nDolby Vision\r\nFlicker-Free\r\nDisplayHDR True Black 500\r\nHiệu chuẩn màu X-Rite</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Hệ điều hành</td>\r\n<td>Windows 11 Home Single Language, English + Microsoft 365 Basic + Office Home 2024 + Lenovo AI Now</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Loại CPU</td>\r\n<td>Intel Core Ultra 7 355, 8 lõi (4P + 4LPE) / 8 luồng, Max Turbo up to 4.7GHz, 12MB Intel Smart Cache</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Kích thước màn hình</td>\r\n<td>14 inches</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Độ phân giải màn hình</td>\r\n<td>1920 x 1200 pixels (WUXGA)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Pin</td>\r\n<td>70Wh, 65W USB-C Slim (2-pin, Wall-mount)</td>\r\n</tr>\r\n<tr class=\"technical-content-item\">\r\n<td>Cổng giao tiếp</td>\r\n<td>3x Thunderbolt 4 (PD 45–65W, DisplayPort 2.1)</td>\r\n</tr>\r\n</tbody>\r\n</table>','Laptop Lenava Slim 16','','inherit','closed','closed','','2306-autosave-v1','','','2026-10-10 06:29:59','2026-10-10 06:29:59','',2306,'https://nhom4ecom.gt.tc/?p=2352',0,'revision','',0);
