INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (1,'Make upload filenames lowercase','Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-09-09 13:42:08',1,NULL,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (2,'Disable admin bar','Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-09-09 13:42:08',1,NULL,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (3,'Allow smilies','Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-09-09 13:42:08',1,NULL,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (4,'Current year','Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-09-09 13:42:08',1,NULL,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (5,'Đánh giá đính kèm ảnh','','// 1. Cho phép Form đánh giá nhận file upload\nadd_action( \'comment_form_top\', \'ms_wc_review_support_upload\' );\nfunction ms_wc_review_support_upload() {\n    if ( is_product() ) {\n        echo \'<script>\n            document.addEventListener(\"DOMContentLoaded\", function() {\n                var form = document.getElementById(\"commentform\");\n                if (form) { form.setAttribute(\"enctype\", \"multipart/form-data\"); }\n            });\n        </script>\';\n    }\n}\n\n// 2. Thêm trường chọn ảnh vào Form\nadd_action( \'comment_form_logged_in_after\', \'ms_add_review_image_field\' );\nadd_action( \'comment_form_after_fields\', \'ms_add_review_image_field\' );\nfunction ms_add_review_image_field() {\n    if ( is_product() ) {\n        echo \'<p class=\"comment-form-image\" style=\"margin: 15px 0;\">\n                <label for=\"review_image\" style=\"display:block; font-weight:600;\">Đính kèm hình ảnh sản phẩm (PNG, JPG, JPEG):</label>\n                <input type=\"file\" name=\"review_image\" id=\"review_image\" accept=\"image/png, image/jpeg, image/jpg\" />\n              </p>\';\n    }\n}\n\n// 3. Xử lý lưu ảnh an toàn\nadd_action( \'comment_post\', \'ms_save_review_image_meta\', 10, 3 );\nfunction ms_save_review_image_meta( $comment_id, $comment_approved, $commentdata ) {\n    if ( isset( $_FILES[\'review_image\'] ) && ! empty( $_FILES[\'review_image\'][\'name\'] ) ) {\n        $allowed_types = array( \'jpg\' => \'image/jpeg\', \'jpeg\' => \'image/jpeg\', \'png\' => \'image/png\' );\n        $file_info = wp_check_filetype( basename( $_FILES[\'review_image\'][\'name\'] ), $allowed_types );\n\n        if ( in_array( $file_info[\'type\'], $allowed_types ) ) {\n            require_once( ABSPATH . \'wp-admin/includes/image.php\' );\n            require_once( ABSPATH . \'wp-admin/includes/file.php\' );\n            require_once( ABSPATH . \'wp-admin/includes/media.php\' );\n\n            $attachment_id = media_handle_upload( \'review_image\', 0 );\n\n            if ( ! is_wp_error( $attachment_id ) ) {\n                add_comment_meta( $comment_id, \'review_image_id\', intval( $attachment_id ) );\n            }\n        }\n    }\n}\n\n// 4. Hiển thị ảnh ra ngoài đánh giá\nadd_action( \'woocommerce_review_after_comment_text\', \'ms_display_review_image\', 10, 1 );\nfunction ms_display_review_image( $comment ) {\n    $image_id = get_comment_meta( $comment->comment_ID, \'review_image_id\', true );\n    if ( $image_id ) {\n        $image_url = wp_get_attachment_image_url( intval( $image_id ), \'medium\' );\n        if ( $image_url ) {\n            echo \'<div class=\"review-attached-image\" style=\"margin-top: 10px;\">\';\n            echo \'<img src=\"\' . esc_url( $image_url ) . \'\" alt=\"\' . esc_attr( \'Ảnh đánh giá sản phẩm\' ) . \'\" style=\"max-width: 150px; border-radius: 6px; border: 1px solid #ddd; padding: 3px;\" />\';\n            echo \'</div>\';\n        }\n    }\n}','','global',0,10,-1,'2026-09-09 13:45:36',1,NULL,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (6,'Đánh giá đính kèm ảnh [CLONE]','','// 1. Cho phép Form đánh giá nhận file upload\nadd_action( \'comment_form_top\', \'ms_wc_review_support_upload\' );\nfunction ms_wc_review_support_upload() {\n    if ( is_product() ) {\n        echo \'<script>\n            document.addEventListener(\"DOMContentLoaded\", function() {\n                var form = document.getElementById(\"commentform\");\n                if (form) { form.setAttribute(\"enctype\", \"multipart/form-data\"); }\n            });\n        </script>\';\n    }\n}\n\n// 2. Thêm trường chọn ảnh vào Form\nadd_action( \'comment_form_logged_in_after\', \'ms_add_review_image_field\' );\nadd_action( \'comment_form_after_fields\', \'ms_add_review_image_field\' );\nfunction ms_add_review_image_field() {\n    if ( is_product() ) {\n        echo \'<p class=\"comment-form-image\" style=\"margin: 15px 0;\">\n                <label for=\"review_image\" style=\"display:block; font-weight:600;\">Đính kèm hình ảnh sản phẩm (PNG, JPG, JPEG):</label>\n                <input type=\"file\" name=\"review_image\" id=\"review_image\" accept=\"image/png, image/jpeg, image/jpg\" />\n              </p>\';\n    }\n}\n\n// 3. Xử lý lưu ảnh an toàn\nadd_action( \'comment_post\', \'ms_save_review_image_meta\', 10, 3 );\nfunction ms_save_review_image_meta( $comment_id, $comment_approved, $commentdata ) {\n    if ( isset( $_FILES[\'review_image\'] ) && ! empty( $_FILES[\'review_image\'][\'name\'] ) ) {\n        $allowed_types = array( \'jpg\' => \'image/jpeg\', \'jpeg\' => \'image/jpeg\', \'png\' => \'image/png\' );\n        $file_info = wp_check_filetype( basename( $_FILES[\'review_image\'][\'name\'] ), $allowed_types );\n\n        if ( in_array( $file_info[\'type\'], $allowed_types ) ) {\n            require_once( ABSPATH . \'wp-admin/includes/image.php\' );\n            require_once( ABSPATH . \'wp-admin/includes/file.php\' );\n            require_once( ABSPATH . \'wp-admin/includes/media.php\' );\n\n            $attachment_id = media_handle_upload( \'review_image\', 0 );\n\n            if ( ! is_wp_error( $attachment_id ) ) {\n                add_comment_meta( $comment_id, \'review_image_id\', intval( $attachment_id ) );\n            }\n        }\n    }\n}\n\n// 4. Hiển thị ảnh ra ngoài đánh giá\nadd_action( \'woocommerce_review_after_comment_text\', \'ms_display_review_image\', 10, 1 );\nfunction ms_display_review_image( $comment ) {\n    $image_id = get_comment_meta( $comment->comment_ID, \'review_image_id\', true );\n    if ( $image_id ) {\n        $image_url = wp_get_attachment_image_url( intval( $image_id ), \'medium\' );\n        if ( $image_url ) {\n            echo \'<div class=\"review-attached-image\" style=\"margin-top: 10px;\">\';\n            echo \'<img src=\"\' . esc_url( $image_url ) . \'\" alt=\"\' . esc_attr( \'Ảnh đánh giá sản phẩm\' ) . \'\" style=\"max-width: 150px; border-radius: 6px; border: 1px solid #ddd; padding: 3px;\" />\';\n            echo \'</div>\';\n        }\n    }\n}','','global',0,10,-1,'2026-09-09 13:58:56',1,NULL,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_snippets` VALUES (7,'Sửa khoảng cách chữ (Nam)','','add_action(\'wp_head\', function () {\n    ?>\n    <style>\n        .woocommerce div.product .woocommerce-product-details__short-description,\n        .woocommerce div.product .woocommerce-tabs,\n        .woocommerce div.product .entry-content {\n            letter-spacing: normal !important;\n            word-spacing: normal !important;\n        }\n    </style>\n    <?php\n});','','global',0,10,-1,'2026-09-11 07:23:21',1,NULL,NULL,NULL);
